    let ram_norm = node_residual_ram as f64 / node_capacity_ram as f64;

    // Align job CPU/RAM ratio with node residual CPU/RAM ratio using cosine-like coupling
    let dot_product = cpu_norm * (job_cpu as f64 / node_capacity_cpu as f64) + ram_norm * (job_ram as f64 / node_capacity_ram as f64);

    // Penalize resource imbalance
